import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 크기 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr02109Controller {
  @Post('/daily-income-statements/generate')
  @HttpCode(200)
  async generateDailyIncomeStatements(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const data = checks.inputOf(req.body);
    const query = checks.queryOf(req.query);
    const periodFrom = data['periodFrom'];
    const periodTo = data['periodTo'];
    if (typeof periodFrom !== 'string' || !DATE_PATTERN.test(periodFrom)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '귀속 기간 시작일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (typeof periodTo !== 'string' || !DATE_PATTERN.test(periodTo)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '귀속 기간 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    const rawWorker = data['dailyWorkerId'];
    let workerId: string | null = null;
    if (rawWorker !== undefined && rawWorker !== null && rawWorker !== '') {
      const n = Number(rawWorker);
      if (!Number.isInteger(n) || n <= 0) {
        throw new ApiError(400, 'VALIDATION_FAILED', '일용직 사원이 올바르지 않습니다.');
      }
      workerId = String(n);
    }
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(page) || page < 0 || !Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호 또는 쪽 크기가 올바르지 않습니다.');
    }
    const pageSize = Math.min(size, MAX_SIZE);

    return transaction(async (db) => {
      const ranges = await db.query(
        'SELECT CAST(:periodFrom AS date) > CAST(:periodTo AS date) AS "invalid"',
        { periodFrom, periodTo },
      );
      if (ranges[0]['invalid']) {
        throw new ApiError(400, 'VALIDATION_FAILED', '귀속 기간 시작일이 종료일보다 늦을 수 없습니다.');
      }
      if (workerId !== null) {
        const workers = await db.query(
          'SELECT daily_worker_id AS "dailyWorkerId" FROM daily_worker WHERE daily_worker_id = CAST(:workerId AS bigint)',
          { workerId },
        );
        if (workers.length === 0) {
          throw new ApiError(404, 'NOT_FOUND', '일용직 사원을 찾을 수 없습니다.');
        }
      }
      const where =
        "closing_status = '마감' AND pay_date >= CAST(:periodFrom AS date) AND pay_date <= CAST(:periodTo AS date)" +
        ' AND (CAST(:workerId AS bigint) IS NULL OR daily_worker_id = CAST(:workerId AS bigint))';
      const counts = await db.query(
        'SELECT COUNT(*) AS "total" FROM daily_payroll WHERE ' + where,
        { periodFrom, periodTo, workerId },
      );
      const total = Number(counts[0]['total']);
      if (total === 0) {
        throw new ApiError(422, 'NO_CLOSED_DAILY_PAYROLL', '대상 기간에 마감된 일용직 급여가 없어 지급명세서를 생성하지 않았습니다.');
      }
      const items = await db.query(
        'SELECT daily_worker_id AS "dailyWorkerId", pay_date AS "payDate", pay_amount AS "payAmount", withholding_tax AS "withholdingTax"' +
          ' FROM daily_payroll WHERE ' + where +
          ' ORDER BY daily_worker_id, pay_date LIMIT :limit OFFSET :offset',
        { periodFrom, periodTo, workerId, limit: pageSize, offset: page * pageSize },
      );
      return { items, page, size: pageSize, total };
    });
  }
}

