import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Form,
  LookupSelect,
  Num,
  Pager,
  RefName,
  Tiles,
  call,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

interface Params {
  periodFrom: string;
  periodTo: string;
  dailyWorkerId: number | string;
}

export default function FnSfr02109Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [periodFrom, setPeriodFrom] = useState('');
  const [periodTo, setPeriodTo] = useState('');
  const [dailyWorkerId, setDailyWorkerId] = useState<number | string>('');
  const [used, setUsed] = useState<Params | undefined>(undefined);
  const [result, setResult] = useState<Page | undefined>(undefined);
  const [error, setError] = useState('');

  async function run(p: Params, pageNo: number) {
    const body: Row = { periodFrom: p.periodFrom, periodTo: p.periodTo };
    if (p.dailyWorkerId !== '') {
      body.dailyWorkerId = p.dailyWorkerId;
    }
    const res = await call<Page>('POST', '/daily-income-statements/generate', role, body, { page: pageNo, size: SIZE });
    setUsed(p);
    setResult(res);
  }

  async function submit() {
    if (!periodFrom || !periodTo) {
      throw new Error('귀속 기간 시작일과 종료일을 입력해 주세요.');
    }
    await run({ periodFrom, periodTo, dailyWorkerId }, 0);
    setError('');
    setOpen(false);
    notify('지급명세서와 원천징수영수증을 생성했습니다.');
  }

  async function movePage(pageNo: number) {
    if (!used) {
      return;
    }
    try {
      await run(used, pageNo);
      setError('');
    } catch (e) {
      setError(e instanceof Error ? e.message : '조회에 실패했습니다.');
    }
  }

  const rows = result ? result.items : [];
  const sumAmount = rows.reduce((s, r) => s + Number(r.payAmount ?? 0), 0);
  const sumTax = rows.reduce((s, r) => s + Number(r.withholdingTax ?? 0), 0);

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>생성 건수</h2>
        <Tiles items={[['마감 급여 건수', result ? <Num value={result.total} /> : '-']]} />
      </section>
      <section className="box span-4">
        <h2>지급 금액</h2>
        <Tiles items={[['현재 쪽 합계', result ? <Num value={sumAmount} /> : '-']]} />
      </section>
      <section className="box span-4">
        <h2>원천징수세액</h2>
        <Tiles items={[['현재 쪽 합계', result ? <Num value={sumTax} /> : '-']]} />
      </section>
      <section className="box span-12">
        <h2>지급명세서</h2>
        <Band total={result ? result.total : undefined}>
          <button type="button" onClick={() => setOpen(true)}>지급명세서 생성</button>
        </Band>
        {used ? (
          <p>
            귀속 기간 <DateText value={used.periodFrom} /> ~ <DateText value={used.periodTo} />
            {used.dailyWorkerId !== '' ? <> · 일용직 사원 <RefName table="daily_worker" role={role} value={used.dailyWorkerId} /></> : null}
            {' '}<Badge value="마감" />
          </p>
        ) : null}
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          columns={[
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table="daily_worker" role={role} value={r.dailyWorkerId} /> },
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r.payDate} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r.payAmount} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r.withholdingTax} /> },
          ]}
          rows={rows}
          empty="지급명세서 생성 버튼을 눌러 기간을 선택하세요."
        />
        {result ? <Pager page={result.page} size={result.size} total={result.total} onPage={movePage} /> : null}
      </section>
      {open ? (
        <Drawer title="지급명세서 생성" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="생성">
            <Field label="귀속 기간 시작일" required>
              <DateInput value={periodFrom} onChange={setPeriodFrom} />
            </Field>
            <Field label="귀속 기간 종료일" required>
              <DateInput value={periodTo} onChange={setPeriodTo} />
            </Field>
            <Field label="일용직 사원" hint="비우면 전체 대상">
              <LookupSelect table="daily_worker" role={role} value={dailyWorkerId} onChange={setDailyWorkerId} placeholder="전체" />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
